"""Tests for the SQLite table rebuild generated by the diff."""

from __future__ import annotations

import sqlite3
from pathlib import Path

from korbase._dialect import SQLITE as LITE
from korbase._diff import diff, render
from korbase._schema import Column, ForeignKey, Index, Snapshot, Table

ID = Column("id", "INTEGER", False, None, True)


def tbl(name: str, *cols: Column, **kw) -> Table:
    """Build a table with an `id` primary key and the given columns."""
    return Table(name, (ID, *cols), kw.pop("pk", ("id",)), f"{name}_pkey", **kw)


def lite(cur: tuple[Table, ...], des: tuple[Table, ...]) -> str:
    """Return the SQLite migration between two sets of tables."""
    a, b = Snapshot({t.name: t for t in cur}), Snapshot({t.name: t for t in des})
    return render(diff(a, b, LITE), LITE)


def run(path: Path, sql: str, setup: str = "") -> sqlite3.Connection:
    """Run `setup`, then the migration `sql` the way the runner will (no transaction)."""
    con = sqlite3.connect(path, isolation_level=None)
    con.executescript(setup)
    assert sql.startswith("-- korbase:no-transaction\n")
    con.executescript(sql)
    return con


def test_nullability_rebuild_without_review():
    out = lite(
        (tbl("a", Column("x", "TEXT", True, None, False)),), (tbl("a", Column("x", "TEXT", False, "''", False)),)
    )
    assert out.startswith("-- korbase:no-transaction\nPRAGMA foreign_keys=OFF;\nBEGIN IMMEDIATE;\n")
    assert 'CREATE TABLE "a__new"' in out and 'INSERT INTO "a__new" ("id", "x") SELECT "id", "x" FROM "a";' in out
    assert 'DROP TABLE "a";\nALTER TABLE "a__new" RENAME TO "a";\n' in out
    assert out.endswith("PRAGMA foreign_key_check;\nCOMMIT;\nPRAGMA foreign_keys=ON;\n")


def test_null_to_not_null_is_reviewed():
    out = lite(
        (tbl("a", Column("x", "TEXT", True, None, False)),), (tbl("a", Column("x", "TEXT", False, None, False)),)
    )
    assert "-- korbase:review a.x becomes NOT NULL" in out


def test_pure_rebuild_has_no_review():
    out = lite(
        (tbl("a", Column("x", "TEXT", False, None, False)),), (tbl("a", Column("x", "TEXT", True, None, False)),)
    )
    assert "korbase:review" not in out


def test_type_change_casts_and_is_reviewed():
    out = lite(
        (tbl("a", Column("x", "TEXT", True, None, False)),), (tbl("a", Column("x", "INTEGER", True, None, False)),)
    )
    assert "-- korbase:review type of a.x changes from TEXT to INTEGER" in out
    assert 'SELECT "id", CAST("x" AS INTEGER) FROM "a";' in out


def test_foreign_key_change():
    p = tbl("p")
    fk = ForeignKey("c_p_fkey", ("p_id",), "p", ("id",), "cascade")
    cols = (Column("p_id", "INTEGER", True, None, False),)
    out = lite((p, tbl("c", *cols)), (p, tbl("c", *cols, foreign_keys=(fk,))))
    assert 'FOREIGN KEY ("p_id") REFERENCES "p" ("id") ON DELETE CASCADE' in out
    assert 'CREATE TABLE "p__new"' not in out and "korbase:review" not in out


def test_unique_change():
    cols = (Column("x", "TEXT", True, None, False),)
    out = lite((tbl("a", *cols),), (tbl("a", *cols, uniques=(("a_x_key", ("x",)),)),))
    assert 'CONSTRAINT "a_x_key" UNIQUE ("x")' in out


def test_indexes_recreated_after_rename():
    cols = (Column("x", "TEXT", True, None, False),)
    idx = (Index("a_x", ("x",), False), Index("a_x_part", ("x",), True, "x > 0"))
    out = lite((tbl("a", *cols, indexes=idx),), (tbl("a", Column("x", "TEXT", False, "''", False), indexes=idx),))
    tail = out.split('RENAME TO "a";\n')[1]
    assert tail.startswith('CREATE INDEX "a_x" ON "a" ("x");\nCREATE UNIQUE INDEX "a_x_part" ON "a" ("x") WHERE x > 0;')


def test_postgres_output_unchanged():
    cur = Snapshot({"a": tbl("a", Column("x", "text", True, None, False))})
    des = Snapshot({"a": tbl("a", Column("x", "text", False, None, False))})
    out = render(diff(cur, des))
    assert "no-transaction" not in out and "__new" not in out and "SET NOT NULL" in out


def test_generated_sql_keeps_rows(tmp_path: Path):
    setup = (
        'CREATE TABLE "p" ("id" INTEGER PRIMARY KEY);'
        'CREATE TABLE "a" ("id" INTEGER PRIMARY KEY, "x" TEXT, "p_id" INTEGER);'
        'CREATE INDEX "a_x_part" ON "a" ("x") WHERE "x" IS NOT NULL;'
        "INSERT INTO p VALUES (1); INSERT INTO a VALUES (1, '10', 1), (2, '20', NULL);"
    )
    fk = ForeignKey("a_p_fkey", ("p_id",), "p", ("id",), "cascade")
    p_id = Column("p_id", "INTEGER", True, None, False)
    cur = (tbl("p"), tbl("a", Column("x", "TEXT", True, None, False), p_id))
    des = (
        tbl("p"),
        tbl(
            "a",
            Column("x", "INTEGER", True, None, False),
            p_id,
            foreign_keys=(fk,),
            indexes=(Index("a_x_part", ("x",), False, '"x" IS NOT NULL'),),
        ),
    )
    con = run(tmp_path / "t.db", lite(cur, des), setup)
    assert con.execute('SELECT "id", "x", typeof("x"), "p_id" FROM "a" ORDER BY "id"').fetchall() == [
        (1, 10, "integer", 1),
        (2, 20, "integer", None),
    ]
    assert con.execute("SELECT name FROM sqlite_master WHERE name = 'a_x_part'").fetchone() is not None
    assert con.execute("SELECT name FROM sqlite_master WHERE name LIKE '%__new'").fetchone() is None
